CREATE SEQUENCE mo_decision_seq START WITH 1 INCREMENT BY 1 NOCACHE;
CREATE TABLE mo_decisiones (id NUMBER(19,0) PRIMARY KEY,tipo VARCHAR2(20 CHAR) NOT NULL,recurso_id NUMBER(19,0) NOT NULL,motivo VARCHAR2(300 CHAR) NOT NULL,bloqueado NUMBER(1,0) NOT NULL,actor_id NUMBER(19,0) NOT NULL,fecha TIMESTAMP(6) NOT NULL,CONSTRAINT mo_recurso_uk UNIQUE(tipo,recurso_id),CONSTRAINT mo_tipo_ck CHECK(tipo IN ('TEMA','COMENTARIO')));
